#!/usr/bin/env bash
#
# Regenerate Lekto's icon set (issue #184).
#
# The set is Lucide geometry converted to `ImageVector` once and committed, so
# the app carries no icon dependency. This script is the whole pipeline: it
# fetches the SVGs at the pinned Lucide tag, runs the pinned Valkyrie CLI, and
# writes the generated Kotlin into the app's `ui.icons` package. Re-run it to
# change the set or to bump the tag; never edit a generated file by hand.
#
# `docs/research/icones-compose.md` settles the choice (Lucide over
# `material-icons-extended`), and `docs/design.md` §5 fixes the geometry. The
# licence obligation is `THIRD-PARTY-NOTICES.md` at the repo root.
#
# Requirements: bash, curl, unzip, java (the Valkyrie CLI is a JVM program).
#
# Usage: tools/icons/fetch.sh

set -euo pipefail

# Pinned so the set is reproducible: the tag names the SVGs, the version and
# digest name the generator. Bumping either is a change to the committed set.
LUCIDE_TAG="1.59.0"
VALKYRIE_VERSION="1.2.1"
VALKYRIE_SHA256="5929fb15395059e566c51dcdb2bed98a2d2e92ad8d344f8186d3b701be6533b3"

# The set, and why each is here. Lucide's names are the file names.
# Navigation icons must read at 24 dp (docs/design.md §5): `library` is a
# barcode and is deliberately absent.
ICONS=(
    book-open       # Library
    bookmark        # Vocabulary
    settings        # Settings
    search          # Library search
    import          # Library import
    arrow-left      # back; directional, mirrors in RTL
    volume-2        # pronounce
    a-large-small   # reading preferences
    x               # close
    trash           # delete
    chevron-left    # previous chapter
    chevron-right   # next chapter
    check           # the chosen entry, on Appearance and App language
    info            # the vault's folder-sync caution
)

# Only these mirror in a right-to-left layout. Valkyrie's `--auto-mirror` is
# all-or-nothing, so they are converted in a second run of their own.
MIRRORED=(arrow-left)

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
SVG_DIR="$REPO_ROOT/tools/icons/lucide"
OUTPUT_DIR="$REPO_ROOT/app/src/commonMain/kotlin/app/lekto/ui/icons"
CACHE_DIR="$REPO_ROOT/tools/icons/.cache"
PACKAGE="app.lekto.ui.icons"
PACK="LektoIcons"

# The first line of every generated file. It carries no tag on purpose: after a
# Lucide bump this script must still recognise — and delete — the files the
# previous tag wrote. The hand-written `LektoIcons.kt` has no marker, so it is
# never removed.
MARKER="// Generated by tools/icons/fetch.sh. Do not edit."

require() {
    command -v "$1" >/dev/null 2>&1 || {
        echo "fetch.sh: $1 is required but not on PATH" >&2
        exit 1
    }
}

require curl
require unzip
require java

# BSD and GNU name the SHA-256 digest tool differently.
if command -v sha256sum >/dev/null 2>&1; then
    sha256() { sha256sum "$@"; }
elif command -v shasum >/dev/null 2>&1; then
    sha256() { shasum -a 256 "$@"; }
else
    echo "fetch.sh: sha256sum or shasum is required" >&2
    exit 1
fi

mkdir -p "$SVG_DIR" "$OUTPUT_DIR" "$CACHE_DIR"

# --- Fetch the SVG sources ----------------------------------------------------
echo "Fetching Lucide $LUCIDE_TAG into tools/icons/lucide/"
for name in "${ICONS[@]}"; do
    curl -fsSL -o "$SVG_DIR/$name.svg" \
        "https://raw.githubusercontent.com/lucide-icons/lucide/$LUCIDE_TAG/icons/$name.svg"
done

# --- Fetch the pinned generator ----------------------------------------------
# Downloaded once and kept in the git-ignored cache; the digest is checked on
# every run, so a tampered or truncated download fails before it writes a file.
VALKYRIE_ZIP="$CACHE_DIR/valkyrie-cli-$VALKYRIE_VERSION.zip"
VALKYRIE_DIR="$CACHE_DIR/valkyrie-cli-$VALKYRIE_VERSION"
if [[ ! -f "$VALKYRIE_ZIP" ]] || ! echo "$VALKYRIE_SHA256  $VALKYRIE_ZIP" | sha256 -c - >/dev/null 2>&1; then
    echo "Downloading Valkyrie CLI $VALKYRIE_VERSION"
    curl -fsSL -o "$VALKYRIE_ZIP" \
        "https://github.com/ComposeGears/Valkyrie/releases/download/cli-$VALKYRIE_VERSION/valkyrie-cli-$VALKYRIE_VERSION.zip"
    echo "$VALKYRIE_SHA256  $VALKYRIE_ZIP" | sha256 -c -
fi
rm -rf "$VALKYRIE_DIR"
mkdir -p "$VALKYRIE_DIR"
unzip -q "$VALKYRIE_ZIP" -d "$VALKYRIE_DIR"
VALKYRIE="$VALKYRIE_DIR/bin/valkyrie"
chmod +x "$VALKYRIE"

# --- Generate -----------------------------------------------------------------
# A scratch tree holds the generator's output so a failure leaves the committed
# set untouched. `--trailing-comma=true` is required: without it ktlint reports
# five `trailing-comma-on-call-site` violations on the generated files.
GENERATED="$(mktemp -d)"
trap 'rm -rf "$GENERATED"' EXIT

generate() { # <input dir> <extra valkyrie flags...>
    local input="$1"
    shift
    "$VALKYRIE" svgxml2imagevector \
        --input-path "$input" \
        --output-path "$GENERATED/out" \
        --package-name "$PACKAGE" \
        --iconpack-name "$PACK" \
        --trailing-comma=true \
        "$@"
}

PLAIN=()
for name in "${ICONS[@]}"; do
    is_mirrored=false
    for mirrored in "${MIRRORED[@]}"; do
        [[ "$name" == "$mirrored" ]] && is_mirrored=true
    done
    $is_mirrored || PLAIN+=("$name")
done

mkdir -p "$GENERATED/plain" "$GENERATED/out"
for name in "${PLAIN[@]}"; do
    cp "$SVG_DIR/$name.svg" "$GENERATED/plain/"
done
generate "$GENERATED/plain"

# One run per mirrored icon, because the flag applies to every file it converts.
for name in "${MIRRORED[@]}"; do
    mkdir -p "$GENERATED/mirrored/$name"
    cp "$SVG_DIR/$name.svg" "$GENERATED/mirrored/$name/"
    generate "$GENERATED/mirrored/$name" --auto-mirror=true
done

# --- Install ------------------------------------------------------------------
# Remove the files this script owns, then write the new ones with the marker.
# `LektoIcons.kt` has no marker and survives.
while IFS= read -r -d '' stale; do
    if [[ "$(head -n 1 "$stale")" == "$MARKER" ]]; then
        rm -f "$stale"
    fi
done < <(find "$OUTPUT_DIR" -maxdepth 1 -name '*.kt' -print0)

for file in "$GENERATED"/out/*.kt; do
    {
        echo "$MARKER"
        echo
        cat "$file"
    } >"$OUTPUT_DIR/$(basename "$file")"
done

echo "Wrote $(find "$OUTPUT_DIR" -maxdepth 1 -name '*.kt' ! -name 'LektoIcons.kt' | wc -l) icons to app/src/commonMain/kotlin/app/lekto/ui/icons/"
echo "Run ./gradlew check to prove the set still compiles and formats."
